    31	 * `U12345`. Prefix with the workspace (team) id so identities don't bleed
    32	 * across orgs: `T0XYZ:U12345` (upper-cased).
    33	 */
    34	export function normalizeSlackUserId(
    35	  teamId: string | null | undefined,
    36	  userId: string | null | undefined,
    37	): string | null {
    38	  if (typeof teamId !== 'string' || typeof userId !== 'string') return null;
    39	  const t = teamId.trim();
    40	  const u = userId.trim();
    41	  if (!t || !u) return null;
    42	  if (!/^[a-z0-9_-]+$/i.test(t) || !/^[a-z0-9_-]+$/i.test(u)) return null;
    43	  return `${t}:${u}`.toUpperCase();
