   405	/**
   406	 * The periodic production caller (registered in `scheduled/jobs.ts`). Re-syncs
   407	 * every active Slack connection's channel-membership graph so joins/leaves
   408	 * converge within the tick cadence and the gate's freshness window keeps a
   409	 * stalled connection fail-closed. Runs on one replica per tick (the TaskScheduler
   410	 * runs-queue claim), iterating connections sequentially — membership sync is not
   411	 * latency-critical.
   412	 *
   413	 * Token resolution ({@link resolveSlackBotIdentity}) prefers the workspace OAuth
   414	 * install and falls back to the connection's own BYO bot credentials, so both
   415	 * managed and BYO Slack connections graph. A connection with neither still
   416	 * fails closed via {@link syncSlackConnectionAcl}.
   417	 */
   418	export async function runSlackAclSyncTick(coreServices: CoreServices): Promise<void> {
   419	  const sql = getDb();
   420	  const connRows = await sql<{ slug: string; organization_id: string }>`
   421			SELECT slug, organization_id
   422			FROM connections
   423			WHERE connector_key = 'slack'
   424			  AND status = 'active'
   425			  AND credential_mode IS NOT NULL
   426			  AND deleted_at IS NULL
   427		`;
   428	  const connections = connRows.map((r) => ({
   429	    id: slugToRuntimeConnectionId(r.slug),
   430	    organization_id: r.organization_id,
   431	  }));
   432	  if (connections.length === 0) return;
   433	
   434	  const installStore = coreServices.getAppInstallationStore();
   435	  const secretStore = coreServices.getSecretStore();
   436	  const slackWeb = createSlackWebApi();
   437	
   438	  const deps: SlackAclSyncDeps = {
   439	    slackWeb,
   440	    resolveBotIdentity: (params) =>
   441	      resolveSlackBotIdentity({ installStore, secretStore, slackWeb }, params),
   442	  };
   443	
   444	  let ok = 0;
   445	  let failed = 0;
   446	  for (const conn of connections) {
   447	    const result = await syncSlackConnectionAcl(deps, {
   448	      connectionId: conn.id,
   449	      organizationId: conn.organization_id,
   450	    });
   451	    if (result.ok) ok += 1;
   452	    else failed += 1;
   453	  }
   454	  logger.info({ connections: connections.length, ok, failed }, 'Slack ACL sync tick complete');
   455	}
