   127	/** GitHub `/repos/{owner}/{repo}/collaborators`, paginated, bare `{login,id}`.
   128	 * Throws on a non-OK response so the sync treats it fail-closed. */
   129	async function fetchRepoCollaborators(
   130	  token: string,
